SELECT subject_key,occurrence_ms,effective_due_ms FROM (SELECT s.message_id AS subject_key,CASE WHEN unixepoch(s.delivery_window_ends_at) IS NULL OR abs(unixepoch(s.delivery_window_ends_at)*1000+CAST(substr(strftime('%f',s.delivery_window_ends_at),4,3) AS INTEGER))>9223372036854 THEN 0 ELSE unixepoch(s.delivery_window_ends_at)*1000+CAST(substr(strftime('%f',s.delivery_window_ends_at),4,3) AS INTEGER) END AS occurrence_ms,CASE WHEN a.attempt_id IS NOT NULL THEN CASE WHEN a.state='failing' AND a.last_failure IN ('corrupt_row','constraint_violated','statement_rejected','refused','other_store_unavailable') THEN CASE WHEN unixepoch(a.next_try_at) IS NULL OR abs(unixepoch(a.next_try_at)*1000+CAST(substr(strftime('%f',a.next_try_at),4,3) AS INTEGER))>9223372036854 THEN 0 ELSE unixepoch(a.next_try_at)*1000+CAST(substr(strftime('%f',a.next_try_at),4,3) AS INTEGER) END ELSE 0 END WHEN s.state!='queued' THEN 0 ELSE CASE WHEN unixepoch(s.delivery_window_ends_at) IS NULL OR abs(unixepoch(s.delivery_window_ends_at)*1000+CAST(substr(strftime('%f',s.delivery_window_ends_at),4,3) AS INTEGER))>9223372036854 THEN 0 ELSE unixepoch(s.delivery_window_ends_at)*1000+CAST(substr(strftime('%f',s.delivery_window_ends_at),4,3) AS INTEGER) END END AS effective_due_ms FROM mail_messages s LEFT JOIN engine_work_attempts a ON a.machine_kind='system_message_expiry' AND a.subject_key=s.message_id WHERE s.state NOT IN ('delivered','cancelled','failed') AND (s.state='queued' AND s.message_kind IN ('notice','deliveryOutcome') AND s.delivery_window_ends_at IS NOT NULL) AND NOT(COALESCE(a.state,'')='retired' AND a.last_failure IN ('corrupt_row','constraint_violated','statement_rejected','refused','other_store_unavailable'))) WHERE effective_due_ms<=?1 ORDER BY effective_due_ms,subject_key LIMIT ?2
